const $=id=>document.getElementById(id),colors=['#b9ed81','#7cbbef','#ecab7e','#ce9eeb','#76d5bf'];let tones=[{f:100,a:1,on:true},{f:200,a:.5,on:true},{f:300,a:.33,on:true}],ms=100,ctx,master,nodes=[],mode=null,playGeneration=0;
function active(){return tones.filter(t=>t.on&&t.a>0)}function lowest(){return [...active()].sort((a,b)=>a.f-b.f)[0]}
function rows(){ $('tones').innerHTML='';tones.forEach((t,i)=>{const row=document.createElement('div');row.className='row';row.innerHTML=`<input type="checkbox" aria-label="Enable tone ${i+1}" ${t.on?'checked':''}><input type="number" aria-label="Frequency ${i+1} in Hz" min="1" max="20000" step="any" value="${t.f}"><span class="amplitude-control"><input type="number" aria-label="Amplitude ${i+1}" min="0" max="1" step="0.001" value="${t.a}"><input type="range" aria-label="Amplitude slider ${i+1}" min="0" max="1" step="0.001" value="${t.a}"></span><button aria-label="Remove tone ${i+1}">×</button>`;const inputs=row.querySelectorAll('input');inputs[0].onchange=()=>{t.on=inputs[0].checked;changed()};[1,2].forEach(k=>inputs[k].onchange=()=>{const n=Number(inputs[k].value),lo=k===1?1:0,hi=k===1?20000:1;if(inputs[k].value===''||!Number.isFinite(n)||n<lo||n>hi){$('error').textContent=`Enter ${k===1?'a frequency from 1 to 20,000 Hz':'an amplitude from 0 to 1'}.`;inputs[k].value=k===1?t.f:t.a;return}t[k===1?'f':'a']=n;$('error').textContent='';inputs[3].value=t.a;changed()});inputs[3].oninput=()=>{t.a=Number(inputs[3].value);inputs[2].value=t.a;changed()};row.querySelector('button').onclick=()=>{tones.splice(i,1);rows();changed()};$('tones').append(row)})}
function changed(){draw();if(!mode)return;const selected=mode==='base'?(lowest()?[lowest()]:[]):active();if(!selected.length){stop();return}if(nodes.length&&selected.every(t=>nodes.some(n=>n.t===t))){const sum=selected.reduce((s,t)=>s+t.a,0);nodes.forEach(n=>{n.o.frequency.setTargetAtTime(n.t.f,ctx.currentTime,.01);n.g.gain.setTargetAtTime(selected.includes(n.t)?n.t.a/sum:0,ctx.currentTime,.015)})}else start(mode)}
function plot(id,list,components){const canvas=$(id),r=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=r.width*dpr;canvas.height=r.height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const w=r.width,h=r.height,L=42,R=14,T=16,B=28,pw=w-L-R,ph=h-T-B;const sum=list.reduce((s,t)=>s+t.a,0),scale=$('yscale').value==='auto'?Math.max(sum,1):Number($('yscale').value);c.font='10px system-ui';c.lineWidth=1;c.strokeStyle='#273341';c.fillStyle='#8999aa';for(let i=0;i<=4;i++){let y=T+ph*i/4;c.beginPath();c.moveTo(L,y);c.lineTo(w-R,y);c.stroke();c.fillText((scale*(1-i/2)).toFixed(1),3,y+4)}for(let i=0;i<=5;i++){let x=L+pw*i/5;c.beginPath();c.moveTo(x,T);c.lineTo(x,h-B);c.stroke();let v=ms*i/5;c.fillText(ms>=1000?(v/1000).toFixed(2)+' s':v.toFixed(1)+' ms',x-15,h-8)}c.save();c.beginPath();c.rect(L,T,pw,ph);c.clip();const maxF=Math.max(1,...list.map(t=>t.f));const dense=maxF*ms/1000>pw/3;const sample=t=>list.reduce((s,v)=>s+v.a*Math.sin(2*Math.PI*v.f*t),0),Y=v=>T+ph/2-v/scale*ph/2;
function trace(fn,color,alpha=1){c.strokeStyle=color;c.globalAlpha=alpha;c.lineWidth=1.5;c.beginPath();const n=Math.min(100000,Math.max(Math.ceil(pw*2),Math.ceil(maxF*ms/1000*24)));if(dense){const buckets=Math.ceil(pw);for(let x=0;x<buckets;x++){let low=Infinity,high=-Infinity;const count=Math.max(2,Math.ceil(n/buckets));for(let j=0;j<count;j++){const v=fn((x+j/count)/buckets*ms/1000);low=Math.min(low,v);high=Math.max(high,v)}c.moveTo(L+x,Y(low));c.lineTo(L+x,Y(high))}}else{for(let i=0;i<=n;i++){let x=L+pw*i/n,y=Y(fn(i/n*ms/1000));if(i===0)c.moveTo(x,y);else c.lineTo(x,y)}}c.stroke()}
if(components&&list.length>1)list.forEach((t,i)=>trace(time=>t.a*Math.sin(2*Math.PI*t.f*time),colors[(i+1)%colors.length],.35));trace(sample,'#b9ed81');c.restore()}
function draw(){const a=active(),b=lowest();plot('wave',a,$('components').checked);plot('baseline',b?[b]:[],false);$('summary').textContent=`${a.length} active tone${a.length===1?'':'s'} · ${ms>=1000?ms/1000+' s':ms+' ms'}`;$('baseLabel').textContent=b?b.f+' Hz':'No active tones'}
function stop(){playGeneration++;if(ctx){const now=ctx.currentTime;nodes.forEach(({o,g})=>{g.gain.cancelScheduledValues(now);g.gain.setTargetAtTime(0,now,.008);o.stop(now+.06)});nodes=[]}mode=null;$('play').textContent='▶ Play mix';$('listenbase').classList.remove('active');$('audioStatus').textContent='Playback stopped.'}
async function start(next){window.dispatchEvent(new Event('harmonic-synth-playing'));stop();const request=playGeneration;const selected=next==='base'?(lowest()?[lowest()]:[]):active();if(!selected.length){$('audioStatus').textContent='Add or enable a tone to listen.';return}try{ctx ||=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();if(request!==playGeneration)return;master ||=ctx.createGain();master.connect(ctx.destination);master.gain.setValueAtTime(Number($('volume').value),ctx.currentTime);const denom=selected.reduce((s,t)=>s+t.a,0);selected.forEach(t=>{if(t.f>=ctx.sampleRate/2)return;const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=t.f;o.type='sine';g.gain.setValueAtTime(0,ctx.currentTime);g.gain.linearRampToValueAtTime(t.a/denom,ctx.currentTime+.025);o.connect(g);g.connect(master);o.start();nodes.push({o,g,t})});mode=next;$('play').textContent=next==='mix'?'■ Stop mix':'▶ Play mix';$('listenbase').classList.toggle('active',next==='base');$('audioStatus').textContent=next==='mix'?'Playing the combined signal.':'Playing the lowest tone. Click again to stop.'}catch(e){$('audioStatus').textContent='Audio could not start. Try opening this app in a browser and pressing Play.'}}
$('play').onclick=()=>mode==='mix'?stop():start('mix');$('listenbase').onclick=()=>mode==='base'?stop():start('base');$('volume').oninput=()=>{if(master)master.gain.setTargetAtTime(Number($('volume').value),ctx.currentTime,.015)};$('add').onclick=()=>{if(tones.length>=24){$('error').textContent='Up to 24 tones can be mixed.';return}const step=tones.length>1?tones[1].f-tones[0].f:(tones[0]?.f||100);const next=tones.length?tones.at(-1).f+(step>0?step:100):100;if(next>20000){$('error').textContent='The next frequency exceeds 20,000 Hz.';return}tones.push({f:Number(next.toFixed(3)),a:.25,on:true});rows();changed()};$('harmonics').onclick=()=>{const base=Number($('base').value),count=Number($('count').value);if(!Number.isFinite(base)||base<1||base>20000||!Number.isInteger(count)||count<1||count>16){$('error').textContent='Use a base of 1–20,000 Hz and 1–16 harmonics.';return}const odd=$('shape').value==='odd';if(base*(odd?2*count-1:count)>20000){$('error').textContent='The highest harmonic must be at most 20,000 Hz.';return}tones=Array.from({length:count},(_,i)=>{const n=odd?2*i+1:i+1;return{f:base*n,a:$('shape').value==='equal'?1:Number((1/n).toFixed(4)),on:true}});$('error').textContent='';rows();changed()};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{tones=b.dataset.preset==='pure'?[{f:100,a:1,on:true}]:b.dataset.preset==='beat'?[{f:100,a:1,on:true},{f:102,a:1,on:true}]:Array.from({length:5},(_,i)=>({f:100*(i+1),a:1/(i+1),on:true}));rows();changed()});function setScale(value){ms=value;$('duration').value=ms;document.querySelectorAll('[data-ms]').forEach(b=>b.classList.toggle('active',Number(b.dataset.ms)===ms));draw()}document.querySelectorAll('[data-ms]').forEach(b=>b.onclick=()=>setScale(Number(b.dataset.ms)));$('duration').onchange=()=>{const n=Number($('duration').value);if(n>=1&&n<=60000)setScale(n);else $('duration').value=ms};$('yscale').onchange=draw;$('components').onchange=draw;new ResizeObserver(draw).observe($('wave'));document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});rows();draw();

$('downloadSynth').onclick=async()=>{const selected=active().map(t=>({...t})),seconds=Number($('exportSeconds').value),volume=Number($('volume').value);if(!selected.length){$('synthExportStatus').textContent='Enable at least one tone with an amplitude above zero.';return}if(!Number.isFinite(seconds)||seconds<.1||seconds>60){$('synthExportStatus').textContent='Choose a download length from 0.1 to 60 seconds.';return}const button=$('downloadSynth');button.disabled=true;$('synthExportStatus').textContent='Preparing your WAV file…';try{const buffer=await HarmonicAudio.renderMix(selected,seconds,volume);HarmonicAudio.download(HarmonicAudio.wav(buffer.getChannelData(0),buffer.sampleRate),'harmonic-lab-mix.wav');$('synthExportStatus').textContent=`Downloaded ${seconds} seconds as a WAV file using the current mix.`}catch(error){$('synthExportStatus').textContent='Could not export audio. Try a shorter duration or another browser.'}finally{button.disabled=false}};

window.HarmonicLab={stop,playMix:()=>start('mix'),setTones:(input)=>{if(!Array.isArray(input)||input.length<1||input.length>24||input.some(t=>!Number.isFinite(t.f)||t.f<1||t.f>20000||!Number.isFinite(t.a)||t.a<0||t.a>1))throw new Error('Invalid harmonic recipe');stop();tones=input.map(t=>({f:t.f,a:t.a,on:t.on!==false}));rows();draw();$('error').textContent='';}};
